use std::ffi::c_void;

/// Opaque handle to the Briev state arena, allocated by `__briev_init_state`.
///
/// Reserved for Phase 1 stateful machinery (register_contract/run_checked);
/// the Phase 0 exports are pure, so this type is not yet constructed.
#[allow(dead_code)]
#[repr(C)]
pub struct BrievState {
    _private: [u8; 0],
}

extern "C" {
    /// Allocate and initialise the Briev runtime state handle.
    pub fn __briev_init_state() -> *mut c_void;
    /// Release the Briev runtime state handle.
    pub fn __glue_release(state: *mut c_void);
    /// Briev export `add`: sum of its two Int arguments.
    pub fn add(a: i64, b: i64) -> i64;
    /// Briev export `within`: 1 if `x` in inclusive [lo, hi], else 0.
    pub fn within(x: i64, lo: i64, hi: i64) -> i64;
    /// Briev export `is_positive`: 1 if `x > 0`, else 0.
    pub fn is_positive(x: i64) -> i64;
    /// Briev export `is_nonneg`: 1 if `x >= 0`, else 0.
    pub fn is_nonneg(x: i64) -> i64;
    /// Briev export `eq`: 1 if `a == b`, else 0.
    pub fn eq(a: i64, b: i64) -> i64;
    /// Briev export `run_checked`: pre -> body -> post orchestration.
    /// Returns 0 when both obligations hold, 1 for a failed precondition,
    /// 2 for a failed postcondition.
    ///
    /// The fn-typed parameters are flat C function pointers: since briev-lang
    /// 43519b01 an exported Briev defn adapts a host pointer into its internal
    /// closure slot through a generated trampoline, so no slot construction is
    /// needed here.
    pub fn run_checked(
        pre: extern "C" fn(i64) -> i64,
        f: extern "C" fn(i64) -> i64,
        post: extern "C" fn(i64, i64) -> i64,
        x: i64,
    ) -> i64;
    /// Briev export `eval_pred`: predicate-as-data dispatch over `x`.
    /// op: 0=GT,1=GE,2=LT,3=LE,4=IN; returns 1 when the inequality holds.
    pub fn eval_pred(op: i64, a: i64, b: i64, x: i64) -> i64;
}
